#!/bin/bash
# Nexus runner, set up at first boot. Paste this whole file into Oracle
# Cloud's "Create compute instance" form: Show advanced options >
# Management > Paste cloud-init script. Fill in the two lines below first.
# (Generated by infra/runner/build-cloud-init.js; edit the sources, not this.)

# 1. The runner's web address, e.g. yourname.duckdns.org
RUNNER_DOMAIN="CHANGE-ME.duckdns.org"

# 2. A long random password, 40 or more letters and digits, that only you
#    and Vercel will know. Paste the same value into Vercel as
#    JUDGE0_AUTH_TOKEN. (Left as CHANGE-ME, one is generated; read it later
#    over SSH with: sudo cat /root/nexus-runner.txt)
RUNNER_TOKEN="CHANGE-ME"

set -euo pipefail
SRC=/opt/nexus-runner-src
mkdir -p "$SRC"

cat > "$SRC/server.js" <<'NEXUS_RUNNER_EOF'
#!/usr/bin/env node
/**
 * Nexus runner: a small code runner that speaks the part of Judge0's API
 * Nexus uses, so the app talks to it exactly as to Judge0 (JUDGE0_URL and
 * JUDGE0_AUTH_TOKEN). Unlike Judge0 it runs on ARM as well as x86, so it fits
 * Oracle Cloud's free Ampere tier.
 *
 * Every run is a fresh, throwaway container from a pinned image, under the
 * gVisor runtime (runsc) when available: no network, read-only filesystem,
 * no capabilities, an unprivileged user, and caps on memory, processes, file
 * size and time. Candidate code arrives on stdin and never touches disk.
 *
 * Needs Node 18+ and Docker. No npm dependencies. Configuration comes from
 * the environment (see infra/runner/README.md).
 */
'use strict'

const http = require('node:http')
const crypto = require('node:crypto')
const os = require('node:os')
const { spawn, execFile } = require('node:child_process')

const VERSION = '1.0.0'
const MAX_BODY_BYTES = 1024 * 1024
const MAX_OUTPUT_BYTES = 1024 * 1024
/** Upper bounds on what any caller may ask for. */
const CEILING = { wallSeconds: 10, memoryKb: 512000 }
/** Container start-up time, on top of the program's own wall-clock limit. */
const STARTUP_ALLOWANCE_MS = 5000

const STATUS = {
  accepted: { id: 3, description: 'Accepted' },
  timeLimit: { id: 5, description: 'Time Limit Exceeded' },
  runtimeError: { id: 11, description: 'Runtime Error (NZEC)' },
  memory: { id: 12, description: 'Runtime Error (out of memory)' },
  output: { id: 12, description: 'Runtime Error (output limit exceeded)' },
  internal: { id: 13, description: 'Internal Error' },
}

function readConfig(env = process.env) {
  return {
    host: env.HOST || '127.0.0.1',
    port: Number(env.PORT || 2358),
    token: env.RUNNER_TOKEN || '',
    runtime: env.RUNNER_RUNTIME || 'runsc',
    docker: env.RUNNER_DOCKER || 'docker',
    pythonImage: env.RUNNER_PYTHON_IMAGE || 'python:3.12.7-slim',
    nodeImage: env.RUNNER_NODE_IMAGE || 'node:22.11.0-slim',
    concurrency: Math.max(1, Number(env.RUNNER_CONCURRENCY) || os.cpus().length),
    queueLimit: Math.max(1, Number(env.RUNNER_QUEUE_LIMIT) || 50),
  }
}

const versionOf = (image) => (/:(\d+(?:\.\d+)*)/.exec(image) || [])[1] || 'unknown'

/** Names follow Judge0's ("Python (3.12.7)") so Nexus detects them the same way. */
function languagesFor(config) {
  return [
    {
      id: 1,
      name: `Python (${versionOf(config.pythonImage)})`,
      image: config.pythonImage,
      command: ['python3', '-I', '-'],
    },
    {
      id: 2,
      name: `JavaScript (Node.js ${versionOf(config.nodeImage)})`,
      image: config.nodeImage,
      command: ['node', '-'],
    },
  ]
}

/**
 * Runs one program in a fresh container and reports Judge0-style status.
 * Resolves with { stdout, stderr, status }; never rejects.
 */
function dockerExecutor(config) {
  return (language, source, limits) =>
    new Promise((resolve) => {
      const name = `nexus-run-${crypto.randomBytes(8).toString('hex')}`
      const memoryMb = Math.max(32, Math.floor(limits.memoryKb / 1024))
      const args = [
        'run',
        '--rm',
        '-i',
        '--pull',
        'never',
        '--name',
        name,
        ...(config.runtime && config.runtime !== 'runc' ? ['--runtime', config.runtime] : []),
        '--network',
        'none',
        '--read-only',
        '--tmpfs',
        '/tmp:rw,nosuid,nodev,size=16m',
        '--memory',
        `${memoryMb}m`,
        '--memory-swap',
        `${memoryMb}m`,
        '--cpus',
        '1',
        '--pids-limit',
        '64',
        '--cap-drop',
        'ALL',
        '--security-opt',
        'no-new-privileges',
        '--user',
        '65534:65534',
        '--ulimit',
        'fsize=1048576',
        '--ulimit',
        'nofile=128:128',
        '--env',
        'HOME=/tmp',
        '--env',
        'PYTHONDONTWRITEBYTECODE=1',
        language.image,
        ...language.command,
      ]
      const child = spawn(config.docker, args, { stdio: ['pipe', 'pipe', 'pipe'] })
      const out = { stdout: [], stderr: [], bytes: 0 }
      let timedOut = false
      let overflow = false
      const stop = () => execFile(config.docker, ['kill', name], () => undefined)
      const timer = setTimeout(
        () => {
          timedOut = true
          stop()
        },
        limits.wallSeconds * 1000 + STARTUP_ALLOWANCE_MS
      )
      const collect = (stream) => (chunk) => {
        out.bytes += chunk.length
        if (out.bytes > MAX_OUTPUT_BYTES) {
          if (!overflow) {
            overflow = true
            stop()
          }
          return
        }
        out[stream].push(chunk)
      }
      child.stdout.on('data', collect('stdout'))
      child.stderr.on('data', collect('stderr'))
      child.stdin.on('error', () => undefined)
      child.stdin.end(source)
      child.on('error', (error) => {
        clearTimeout(timer)
        resolve({ stdout: '', stderr: String(error.message), status: STATUS.internal })
      })
      child.on('close', (code) => {
        clearTimeout(timer)
        const stdout = Buffer.concat(out.stdout).toString('utf8')
        const stderr = Buffer.concat(out.stderr).toString('utf8')
        let status = STATUS.accepted
        if (timedOut) status = STATUS.timeLimit
        else if (overflow) status = STATUS.output
        // 125-127: Docker itself failed (daemon, runtime, missing image).
        else if (code >= 125 && code <= 127) status = STATUS.internal
        else if (code === 137) status = STATUS.memory
        else if (code !== 0) status = STATUS.runtimeError
        resolve({ stdout, stderr, status })
      })
    })
}

/** At most `concurrency` runs at once; at most `queueLimit` waiting. */
function createQueue(concurrency, queueLimit) {
  let active = 0
  const waiting = []
  const next = () => {
    if (active >= concurrency || waiting.length === 0) return
    active += 1
    const { task, resolve } = waiting.shift()
    task()
      .then(resolve)
      .finally(() => {
        active -= 1
        next()
      })
  }
  return {
    full: () => waiting.length >= queueLimit,
    push: (task) =>
      new Promise((resolve) => {
        waiting.push({ task, resolve })
        next()
      }),
  }
}

function sameToken(given, expected) {
  const a = Buffer.from(String(given || ''))
  const b = Buffer.from(expected)
  return a.length === b.length && crypto.timingSafeEqual(a, b)
}

function readBody(req) {
  return new Promise((resolve, reject) => {
    const chunks = []
    let size = 0
    req.on('data', (chunk) => {
      size += chunk.length
      if (size > MAX_BODY_BYTES) {
        reject(Object.assign(new Error('Request too large'), { statusCode: 413 }))
        req.destroy()
        return
      }
      chunks.push(chunk)
    })
    req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')))
    req.on('error', reject)
  })
}

const clamp = (value, low, high, fallback) => {
  const n = Number(value)
  return Number.isFinite(n) && n > 0 ? Math.min(high, Math.max(low, n)) : fallback
}

/**
 * The HTTP server. `execute` is injectable so tests can run without Docker.
 */
function createRunnerServer(options = {}) {
  const config = { ...readConfig(), ...options.config }
  if (!config.token) throw new Error('RUNNER_TOKEN is required')
  const languages = languagesFor(config)
  const execute = options.execute || dockerExecutor(config)
  const queue = createQueue(config.concurrency, config.queueLimit)
  let served = 0

  const send = (res, status, body) => {
    res.writeHead(status, { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' })
    res.end(JSON.stringify(body))
  }

  return http.createServer(async (req, res) => {
    try {
      const url = new URL(req.url || '/', 'http://runner')
      if (!sameToken(req.headers['x-auth-token'], config.token)) {
        return send(res, 401, { error: 'Unauthorized' })
      }
      if (req.method === 'GET' && url.pathname === '/about') {
        return send(res, 200, { name: 'Nexus runner', version: VERSION, runs: served })
      }
      if (req.method === 'GET' && url.pathname === '/languages') {
        return send(
          res,
          200,
          languages.map(({ id, name }) => ({ id, name }))
        )
      }
      if (req.method === 'POST' && url.pathname === '/submissions') {
        const body = JSON.parse(await readBody(req))
        const base64 = url.searchParams.get('base64_encoded') === 'true'
        const language = languages.find((l) => l.id === Number(body.language_id))
        if (!language) return send(res, 422, { error: 'Unknown language_id' })
        if (body.enable_network) return send(res, 422, { error: 'Network access is not available' })
        if (typeof body.source_code !== 'string')
          return send(res, 422, { error: 'source_code is required' })
        if (queue.full()) return send(res, 503, { error: 'Queue is full' })
        const source = base64
          ? Buffer.from(body.source_code, 'base64').toString('utf8')
          : body.source_code
        const limits = {
          wallSeconds: clamp(body.wall_time_limit, 1, CEILING.wallSeconds, 5),
          memoryKb: clamp(body.memory_limit, 32000, CEILING.memoryKb, 128000),
        }
        const result = await queue.push(() => execute(language, source, limits))
        served += 1
        const encode = (text) => (base64 ? Buffer.from(text, 'utf8').toString('base64') : text)
        return send(res, 201, {
          token: crypto.randomUUID(),
          stdout: encode(result.stdout),
          stderr: encode(result.stderr),
          compile_output: null,
          message: null,
          status: result.status,
        })
      }
      return send(res, 404, { error: 'Not found' })
    } catch (error) {
      const statusCode = (error && error.statusCode) || (error instanceof SyntaxError ? 400 : 500)
      return send(res, statusCode, { error: statusCode === 500 ? 'Runner error' : error.message })
    }
  })
}

function main() {
  const config = readConfig()
  const server = createRunnerServer({ config })
  server.listen(config.port, config.host, () => {
    console.log(
      `Nexus runner ${VERSION} on ${config.host}:${config.port}, runtime ${config.runtime}, ` +
        `${config.concurrency} at a time`
    )
  })
  const shutdown = () => server.close(() => process.exit(0))
  process.on('SIGTERM', shutdown)
  process.on('SIGINT', shutdown)
}

if (require.main === module) main()

module.exports = { createRunnerServer, languagesFor, readConfig, STATUS, VERSION }
NEXUS_RUNNER_EOF

cat > "$SRC/setup.sh" <<'NEXUS_RUNNER_EOF'
#!/usr/bin/env bash
# Sets up the Nexus runner on a fresh Ubuntu 24.04 server, ARM64 or x86-64
# (including Oracle Cloud's free Ampere A1): Docker, the gVisor sandbox,
# pinned Python and Node images, the runner as a locked-down service, and
# Caddy in front for HTTPS. Safe to run again; it keeps the existing token.
#
# Usage, as root on the server, from the folder holding this script and server.js:
#   bash setup.sh runner.example.com [you@example.com]
# or unattended at first boot through oracle-cloud-init.sh. RUNNER_TOKEN in
# the environment sets the access token (40+ characters); otherwise one is
# generated. The email is optional (certificate expiry notices).
#
# Ports 80 and 443 must be open in your cloud provider's firewall (on Oracle:
# the subnet's security list). HTTPS starts as soon as the domain's DNS points
# at this server; Caddy keeps retrying until it does.
set -euo pipefail

DOMAIN="${1:?Usage: bash setup.sh <domain> [email for HTTPS certificates]}"
EMAIL="${2:-}"
HERE="$(cd "$(dirname "$0")" && pwd)"
DIR="/opt/nexus-runner"
ENV_FILE="/etc/nexus-runner.env"
PYTHON_IMAGE="python:3.12.7-slim"
NODE_IMAGE="node:22.11.0-slim"
CADDY_IMAGE="caddy:2.8.4"

say() { printf '\n== %s\n' "$*"; }
# First boot often has unattended upgrades holding the package lock; wait for it.
apt_get() { apt-get -o DPkg::Lock::Timeout=900 -q "$@"; }

if [ "$(id -u)" -ne 0 ]; then
  echo "Run this as root (sudo bash setup.sh ...)." >&2
  exit 1
fi
if [ ! -f "$HERE/server.js" ]; then
  echo "server.js must be next to this script." >&2
  exit 1
fi
if ! grep -q 'VERSION_ID="24.04"' /etc/os-release; then
  echo "Warning: written for Ubuntu 24.04; this is $(. /etc/os-release && echo "$PRETTY_NAME")."
fi

say "1/6 Packages"
apt_get update
apt_get install -y docker.io nodejs curl gnupg ca-certificates openssl
systemctl enable --now docker
NODE_MAJOR="$(node -p 'process.versions.node.split(".")[0]')"
if [ "$NODE_MAJOR" -lt 18 ]; then
  echo "Node.js 18+ is needed; this system has $(node --version). Use Ubuntu 24.04." >&2
  exit 1
fi

say "2/6 gVisor sandbox"
if ! command -v runsc > /dev/null; then
  curl -fsSL https://gvisor.dev/archive.key | gpg --dearmor --yes -o /usr/share/keyrings/gvisor-archive-keyring.gpg
  echo "deb [arch=$(dpkg --print-architecture) signed-by=/usr/share/keyrings/gvisor-archive-keyring.gpg] https://storage.googleapis.com/gvisor/releases release main" \
    > /etc/apt/sources.list.d/gvisor.list
  apt_get update
  apt_get install -y runsc
fi
# The package registers itself with Docker; make sure Docker has picked it up.
runsc install > /dev/null 2>&1 || true
systemctl restart docker
RUNTIME="runsc"
if ! docker run --rm --runtime=runsc hello-world > /dev/null 2>&1; then
  if [ "${ALLOW_RUNC:-}" = "1" ]; then
    echo "gVisor did not work; continuing with plain Docker isolation because ALLOW_RUNC=1."
    RUNTIME="runc"
  else
    echo "gVisor (runsc) could not run a container on this server." >&2
    echo "Fix that, or rerun with ALLOW_RUNC=1 to use plain Docker isolation (weaker)." >&2
    exit 1
  fi
fi
echo "Sandbox runtime: $RUNTIME"

say "3/6 Language images"
docker pull -q "$PYTHON_IMAGE"
docker pull -q "$NODE_IMAGE"

say "4/6 Runner service"
id nexus-runner > /dev/null 2>&1 || useradd --system --no-create-home --shell /usr/sbin/nologin nexus-runner
# Docker access is what lets the runner start sandboxes; it needs nothing else.
usermod -aG docker nexus-runner
mkdir -p "$DIR"
install -m 0644 "$HERE/server.js" "$DIR/server.js"

TOKEN="${RUNNER_TOKEN:-}"
if [ -n "$TOKEN" ] && [ "${#TOKEN}" -lt 40 ]; then
  echo "RUNNER_TOKEN must be at least 40 characters." >&2
  exit 1
fi
if [ -z "$TOKEN" ] && [ -f "$ENV_FILE" ]; then
  TOKEN="$(grep '^RUNNER_TOKEN=' "$ENV_FILE" | cut -d= -f2- || true)"
fi
[ -n "$TOKEN" ] || TOKEN="$(openssl rand -hex 32)"
cat > "$ENV_FILE" <<ENV
HOST=127.0.0.1
PORT=2358
RUNNER_TOKEN=${TOKEN}
RUNNER_RUNTIME=${RUNTIME}
RUNNER_PYTHON_IMAGE=${PYTHON_IMAGE}
RUNNER_NODE_IMAGE=${NODE_IMAGE}
DOCKER_CONFIG=/tmp/.docker
ENV
chown root:nexus-runner "$ENV_FILE"
chmod 640 "$ENV_FILE"

cat > /etc/systemd/system/nexus-runner.service <<'UNIT'
[Unit]
Description=Nexus code runner
After=docker.service
Requires=docker.service

[Service]
User=nexus-runner
Group=nexus-runner
EnvironmentFile=/etc/nexus-runner.env
ExecStart=/usr/bin/node /opt/nexus-runner/server.js
Restart=always
RestartSec=2
NoNewPrivileges=true
ProtectSystem=full
ProtectHome=true
PrivateTmp=true

[Install]
WantedBy=multi-user.target
UNIT
systemctl daemon-reload
systemctl enable nexus-runner
systemctl restart nexus-runner

say "5/6 HTTPS with Caddy"
{
  if [ -n "$EMAIL" ]; then printf '{\n\temail %s\n}\n\n' "$EMAIL"; fi
  cat <<CADDY
${DOMAIN} {
	encode gzip
	reverse_proxy 127.0.0.1:2358
}
CADDY
} > "$DIR/Caddyfile"
docker rm -f nexus-caddy > /dev/null 2>&1 || true
docker run -d --name nexus-caddy --restart always --network host \
  -v "$DIR/Caddyfile:/etc/caddy/Caddyfile:ro" \
  -v nexus-caddy-data:/data -v nexus-caddy-config:/config \
  "$CADDY_IMAGE" > /dev/null

say "6/6 Firewall"
if [ -f /etc/iptables/rules.v4 ] && command -v netfilter-persistent > /dev/null; then
  # Oracle's Ubuntu images ship iptables rules that reject everything but SSH.
  for port in 80 443; do
    iptables -C INPUT -p tcp --dport "$port" -m state --state NEW -j ACCEPT 2> /dev/null ||
      iptables -I INPUT 1 -p tcp --dport "$port" -m state --state NEW -j ACCEPT
  done
  netfilter-persistent save > /dev/null
else
  apt_get install -y ufw
  ufw allow OpenSSH
  ufw allow 80/tcp
  ufw allow 443/tcp
  ufw --force enable
fi

echo "Waiting for the runner to answer..."
for _ in $(seq 1 15); do
  if curl -fsS -H "X-Auth-Token: ${TOKEN}" http://127.0.0.1:2358/about > /dev/null 2>&1; then
    break
  fi
  sleep 2
done
curl -fsS -H "X-Auth-Token: ${TOKEN}" http://127.0.0.1:2358/languages || {
  echo "The runner did not answer. Check: journalctl -u nexus-runner -n 50" >&2
  exit 1
}

# A real run through the sandbox, end to end.
PROBE="$(printf 'print(6 * 7)' | base64)"
RESULT="$(curl -fsS -X POST -H "X-Auth-Token: ${TOKEN}" -H 'Content-Type: application/json' \
  -d "{\"language_id\":1,\"source_code\":\"${PROBE}\"}" \
  'http://127.0.0.1:2358/submissions?base64_encoded=true&wait=true')"
if echo "$RESULT" | grep -q '"stdout":"NDIK"'; then
  echo
  echo "Sandboxed Python run: OK"
else
  echo "Sandboxed run failed: $RESULT" >&2
  exit 1
fi

# For reading back later over SSH: sudo cat /root/nexus-runner.txt
umask 077
printf 'JUDGE0_URL=https://%s\nJUDGE0_AUTH_TOKEN=%s\n' "$DOMAIN" "$TOKEN" > /root/nexus-runner.txt

cat <<DONE

The Nexus runner is running. Add these to the Nexus project in Vercel
(Settings > Environment Variables, Production), then redeploy:

  JUDGE0_URL=https://${DOMAIN}
  JUDGE0_AUTH_TOKEN=${TOKEN}

Keep the token secret; it is stored in ${ENV_FILE}.
Then open /admin/reviews in Nexus: the Code runner panel should say
"Nexus runner 1.0.0 connected".
DONE
NEXUS_RUNNER_EOF

case "$RUNNER_DOMAIN" in
  *CHANGE-ME*)
    echo "Set RUNNER_DOMAIN at the top of the cloud-init script, then recreate the instance." >&2
    exit 1
    ;;
esac
if [ "$RUNNER_TOKEN" = "CHANGE-ME" ]; then
  RUNNER_TOKEN=""
fi
RUNNER_TOKEN="$RUNNER_TOKEN" bash "$SRC/setup.sh" "$RUNNER_DOMAIN"
